export * as ScrollArea from './scroll-area.tsx';
export type {
  BoxOwnProps as ScrollAreaBoxOwnProps,
  BoxProps as ScrollAreaBoxProps,
  ViewportOwnProps as ScrollAreaViewportOwnProps,
  ViewportProps as ScrollAreaViewportProps,
} from './scroll-area.tsx';

@layer hj.components {
  /* Customise: --hj-scroll-area-fade (edge fade length, 24px) · --hj-scroll-area-thumb (colour) */
  .hj-scroll-area {
    position: relative;
    min-height: 0;
    overflow: hidden;
  }
  .hj-scroll-area-viewport {
    height: 100%;
    max-height: inherit;
    overscroll-behavior: contain;
    outline: none;
  }
  .hj-scroll-area-viewport:focus-visible {
    outline: 2px solid var(--hj-focus);
    outline-offset: -2px;
  }
  /* edges fade only where there is more to see */
  .hj-scroll-area-viewport[data-fade] {
    --_f: var(--hj-scroll-area-fade, 24px);
    mask-image:
      linear-gradient(
        to bottom,
        transparent 0,
        black min(var(--scroll-area-overflow-y-start, 0px), var(--_f)),
        black calc(100% - min(var(--scroll-area-overflow-y-end, 0px), var(--_f))),
        transparent 100%
      ),
      linear-gradient(
        to right,
        transparent 0,
        black min(var(--scroll-area-overflow-x-start, 0px), var(--_f)),
        black calc(100% - min(var(--scroll-area-overflow-x-end, 0px), var(--_f))),
        transparent 100%
      );
    mask-composite: intersect;
  }

  .hj-scroll-area-content {
    min-width: 100%;
  }

  /* a thin overlay rail: invisible at rest, there when you reach for it */
  .hj-scroll-area-scrollbar {
    display: flex;
    padding: 2px;
    opacity: 0;
    pointer-events: none;
    touch-action: none;
    user-select: none;
    transition: opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-scroll-area-scrollbar[data-orientation='vertical'] {
    width: 10px;
    justify-content: center;
  }
  .hj-scroll-area-scrollbar[data-orientation='horizontal'] {
    height: 10px;
    align-items: center;
  }
  .hj-scroll-area-scrollbar[data-hovering],
  .hj-scroll-area-scrollbar[data-scrolling] {
    opacity: 1;
    pointer-events: auto;
  }
  .hj-scroll-area-scrollbar[data-scrolling] {
    transition-duration: 0ms;
  }

  .hj-scroll-area-thumb {
    border-radius: var(--hj-radius-pill);
    background: var(--hj-scroll-area-thumb, color-mix(in srgb, var(--hj-fg) 28%, transparent));
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-scroll-area-scrollbar[data-orientation='vertical'] .hj-scroll-area-thumb {
    width: 6px;
  }
  .hj-scroll-area-scrollbar[data-orientation='horizontal'] .hj-scroll-area-thumb {
    height: 6px;
  }
  /* reaching for it: the thumb firms up and widens (by scale, not width) */
  .hj-scroll-area-scrollbar[data-orientation='vertical']:hover .hj-scroll-area-thumb {
    background: color-mix(in srgb, var(--hj-fg) 45%, transparent);
    transform: scaleX(1.34);
  }
  .hj-scroll-area-scrollbar[data-orientation='horizontal']:hover .hj-scroll-area-thumb {
    background: color-mix(in srgb, var(--hj-fg) 45%, transparent);
    transform: scaleY(1.34);
  }
  .hj-scroll-area-corner {
    background: transparent;
  }
}

'use client';
import { ScrollArea as Base } from '@base-ui/react/scroll-area';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

export const Root: HanjiPart<typeof Base.Root> = part(
  Base.Root,
  'ScrollArea.Root',
  'hj-scroll-area',
);
export const Content: HanjiPart<typeof Base.Content> = part(
  Base.Content,
  'ScrollArea.Content',
  'hj-scroll-area-content',
);
export const Thumb: HanjiPart<typeof Base.Thumb> = part(
  Base.Thumb,
  'ScrollArea.Thumb',
  'hj-scroll-area-thumb',
);
export const Corner: HanjiPart<typeof Base.Corner> = part(
  Base.Corner,
  'ScrollArea.Corner',
  'hj-scroll-area-corner',
);

export interface ViewportOwnProps {
  /** Fade the edges where content continues (uses Base UI's overflow distances). @default true */
  fade?: boolean;
}
export interface ViewportProps extends ViewportOwnProps, Base.Viewport.Props {}

/** The scrolling element. Focusable when it overflows, so the keyboard can scroll it. */
export function Viewport(props: ViewportProps): React.ReactElement {
  const config = useHanjiConfig();
  const { fade = true, className, ...rest } = withDefaults(config, 'ScrollArea.Viewport', props);
  return (
    <Base.Viewport
      {...rest}
      data-fade={flag(fade)}
      className={cls(config, 'ScrollArea.Viewport', 'hj-scroll-area-viewport', className)}
    />
  );
}

/** The thin overlay track. Renders its Thumb when given no children. */
export function Scrollbar(props: Base.Scrollbar.Props): React.ReactElement {
  const config = useHanjiConfig();
  const { className, children, ...rest } = withDefaults(config, 'ScrollArea.Scrollbar', props);
  return (
    <Base.Scrollbar
      {...rest}
      className={cls(config, 'ScrollArea.Scrollbar', 'hj-scroll-area-scrollbar', className)}
    >
      {children ?? <Thumb />}
    </Base.Scrollbar>
  );
}

export interface BoxOwnProps {
  /** Which scrollbars to draw. @default 'vertical' */
  orientation?: 'vertical' | 'horizontal' | 'both';
  /** Fade the edges where content continues. @default true */
  fade?: boolean;
}
export interface BoxProps extends BoxOwnProps, Base.Root.Props {}

/** Shorthand: Root + Viewport + Content + scrollbar(s). Size it like any box. */
export function Box({
  orientation = 'vertical',
  fade,
  children,
  ...root
}: BoxProps): React.ReactElement {
  return (
    <Root {...root}>
      <Viewport fade={fade}>
        <Content>{children}</Content>
      </Viewport>
      {orientation !== 'horizontal' ? <Scrollbar orientation="vertical" /> : null}
      {orientation !== 'vertical' ? <Scrollbar orientation="horizontal" /> : null}
      {orientation === 'both' ? <Corner /> : null}
    </Root>
  );
}
